def main(argv: Sequence[str]) -> int:
    try:
        opts = parse_args(argv)
    except ParseError as exc:
        print_parse_error(exc)
        return exc.code

    binary_path = str(Path(argv[0]).resolve())
    config_dir = str(Path.home() / ".lnav")
    work_dir = f"/tmp/lnav-user-{os.getuid()}-work"

    if opts.help:
        sys.stderr.write(
            HELP_TEMPLATE.format(
                argv0=argv[0],
                binary_path=binary_path,
                config_dir=config_dir,
                work_dir=work_dir,
            )
        )
        return 0

    if opts.version and not opts.internal_help:
        sys.stdout.write(f"{VERSION}\n")
        return 0

    if opts.update_formats:
        sys.stdout.write(
            "No formats from git repositories found, use 'lnav -i extra' to install third-party formats\n"
        )
        return 0

    if opts.check_config:
        return 0

    if opts.management_mode:
        if not opts.paths:
            sys.stderr.write(MANAGEMENT_HELP)
            return 1
        sys.stderr.write(MANAGEMENT_HELP)
        return 1

    if opts.install_arg is not None:
        return handle_install(opts.install_arg)

    if opts.internal_help:
        if not opts.headless and not sys.stdout.isatty():
            print_ui_error()
            return 1
        sys.stdout.write(load_internal_help())
        return 0

    if opts.debug_file:
        try:
            Path(opts.debug_file).write_text("", encoding="utf-8")
        except OSError:
            pass

    try:
        since_dt = parse_cutoff(opts.since_text, "since") if opts.since_text else None
        until_dt = parse_cutoff(opts.until_text, "until") if opts.until_text else None
    except RuntimeCliError as exc:
        print_runtime_error(exc)
        return exc.code

    runtime = RuntimeContext(
        argv0=argv[0],
        opts=opts,
        since_dt=since_dt,
        until_dt=until_dt,
    )

    try:
        state = runtime.load_state()
    except RuntimeCliError as exc:
        print_runtime_error(exc)
        return exc.code

    if not opts.headless and not sys.stdout.isatty():
        for line in runtime.deferred_errors:
            sys.stderr.write(f"{line}\n")
        print_ui_error()
        return 1

    for line in runtime.deferred_errors:
        sys.stderr.write(f"{line}\n")
        if not line.endswith("\n"):
            pass

    try:
        execute_commands(runtime, state)
    except RuntimeCliError as exc:
        print_runtime_error(exc)
        return exc.code

    if state.explicit_output is not None:
        sys.stdout.write(state.explicit_output)
        return 0

    if state.last_query is not None and not state.had_command_error:
        sys.stdout.write(format_table(state.last_query))
        return 0

    if state.had_command_error:
        return 0

    if opts.quiet:
        return 0

    if state.visible_entries:
        sys.stdout.write(render_log_lines(state.visible_entries))
    elif state.plain_lines:
        sys.stdout.write(render_plain_lines(state.plain_lines))
    return 0


class RuntimeContext:
    def __init__(
        self,
        *,
        argv0: str,
        opts: Options,
        since_dt: datetime | None,
        until_dt: datetime | None,
    ) -> None:
        self.argv0 = argv0
        self.opts = opts
        self.since_dt = since_dt
        self.until_dt = until_dt
        self.deferred_errors: list[str] = []

    def load_state(self) -> State:
        sources: list[Source] = []

        for path in self.expand_paths(self.opts.paths):
            if path == "-":
                sources.append(self.load_stdin_explicit())
                continue
            source = self.load_path(path)
            if source is not None:
                sources.append(source)

        for shell_command in self.opts.shell_commands:
            sources.append(self.load_shell_output(shell_command))

        if self.opts.prepend_stdin_timestamps and "-" not in self.opts.paths and not self.opts.no_default:
            if not sys.stdin.isatty():
                sources.append(self.load_stdin_implicit())

        if not sources:
            default_source = self.load_default_source()
            if default_source is not None:
                sources.append(default_source)

        if not sources:
            if self.opts.no_default:
                return State(all_entries=[], visible_entries=[], plain_lines=[])
            raise RuntimeCliError(
                1,
                [
                    "  error: nothing to do",
                    " reason: no files given or default files found",
                    " = help: use the “-N” option to open lnav without loading any files",
                ],
            )

        log_sources = [src for src in sources if src.log_entries]
        plain_sources = [src for src in sources if src.plain_lines and not src.log_entries]

        if log_sources:
            entries: list[Entry] = []
            out_of_range_errors: list[list[str]] = []
            for src in log_sources:
                filtered = self.apply_time_cutoffs(src)
                if filtered is None:
                    out_of_range_errors.append(self.build_out_of_range_error(src))
                    continue
                entries.extend(filtered)

            if out_of_range_errors:
                raise RuntimeCliError(1, [line for block in out_of_range_errors for line in block])

            entries.sort(key=lambda entry: (entry.log_time, entry.path, entry.log_line))
            for idx, entry in enumerate(entries):
                idle = 0 if idx == 0 else int((entry.log_time - entries[idx - 1].log_time).total_seconds() * 1000)
                entry.log_idle_msecs = idle
                entry.log_line = idx
            return State(all_entries=list(entries), visible_entries=list(entries), plain_lines=[])

        plain_lines: list[PlainLine] = []
        for src in plain_sources:
            plain_lines.extend(src.plain_lines)
        return State(all_entries=[], visible_entries=[], plain_lines=plain_lines)

    def expand_paths(self, paths: Sequence[str]) -> list[str]:
        expanded: list[str] = []
        for path in paths:
            expanded.append(path)
        return expanded

    def load_default_source(self) -> Source | None:
        if self.opts.no_default:
            return None
        for path in ("/var/log/messages", "/var/log/syslog"):
            if Path(path).exists():
                return self.load_path(path)
        return None

    def load_path(self, path: str) -> Source | None:
        target = Path(path)
        if not target.exists():
            self.deferred_errors.extend(
                [
                    f"  error: unable to open file: {path}",
                    " reason: No such file or directory",
                ]
            )
            return None

        if target.is_dir():
            return self.load_directory(target)

        return self.load_file(target, display_path=path)

    def load_directory(self, directory: Path) -> Source:
        if self.opts.recursive:
            files = sorted([p for p in directory.rglob("*") if p.is_file()], key=lambda p: str(p))
        else:
            files = sorted([p for p in directory.iterdir() if p.is_file()], key=lambda p: str(p))

        sources = [self.load_file(path, display_path=str(path)) for path in files]
        log_entries = [entry for src in sources if src is not None for entry in src.log_entries]
        plain_lines = [line for src in sources if src is not None for line in src.plain_lines]

        if log_entries:
            return Source(display_path=str(directory), kind="directory", log_entries=log_entries, plain_lines=[])
        return Source(display_path=str(directory), kind="directory", log_entries=[], plain_lines=plain_lines)

    def load_file(self, path: Path, *, display_path: str) -> Source:
        text = read_text_file(path)
        lines = text.splitlines()
        mtime = datetime.fromtimestamp(path.stat().st_mtime, timezone.utc).astimezone().replace(tzinfo=None)
        parsed = [parse_line(line) for line in lines]
        if any(entry is not None for entry in parsed):
            entries: list[Entry] = []
            for idx, parsed_entry in enumerate(parsed):
                if parsed_entry is None:
                    continue
                stamp, body = parsed_entry
                entries.append(
                    Entry(
                        log_line=idx,
                        log_time=stamp,
                        raw_line=lines[idx],
                        body=body,
                        level=detect_level(body),
                        path=str(path.resolve()),
                        log_idle_msecs=0,
                    )
                )
            return Source(display_path=display_path, kind="file", log_entries=entries, plain_lines=[], file_mtime=mtime)

        plain_lines = [PlainLine(raw_line=line, path=str(path.resolve()), line_no=i) for i, line in enumerate(lines)]
        return Source(display_path=display_path, kind="file", log_entries=[], plain_lines=plain_lines, file_mtime=mtime)

    def load_shell_output(self, command: str) -> Source:
        proc = subprocess.run(
            command,
            shell=True,
            text=True,
            capture_output=True,
            check=False,
        )
        text = proc.stdout
        lines = text.splitlines()
        parsed = [parse_line(line) for line in lines]
        if any(entry is not None for entry in parsed):
            entries = []
            for idx, parsed_entry in enumerate(parsed):
                if parsed_entry is None:
                    continue
                stamp, body = parsed_entry
                entries.append(
                    Entry(
                        log_line=idx,
                        log_time=stamp,
                        raw_line=lines[idx],
                        body=body,
                        level=detect_level(body),
                        path="<shell>",
                        log_idle_msecs=0,
                    )
                )
            return Source(display_path="<shell>", kind="shell", log_entries=entries, plain_lines=[])

        plain_lines = [PlainLine(raw_line=line, path="<shell>", line_no=i) for i, line in enumerate(lines)]
        return Source(display_path="<shell>", kind="shell", log_entries=[], plain_lines=plain_lines)

    def load_stdin_explicit(self) -> Source:
        return self._load_stdin_source(explicit=True)

    def load_stdin_implicit(self) -> Source:
        return self._load_stdin_source(explicit=False)

    def _load_stdin_source(self, *, explicit: bool) -> Source:
        data = sys.stdin.read()
        lines = data.splitlines()
        if self.opts.prepend_stdin_timestamps:
            rendered_lines = [ensure_timestamp(line) for line in lines]
        else:
            rendered_lines = lines

        parsed = [parse_line(line) for line in rendered_lines]
        if any(entry is not None for entry in parsed):
            entries = []
            for idx, parsed_entry in enumerate(parsed):
                if parsed_entry is None:
                    continue
                stamp, body = parsed_entry
                entries.append(
                    Entry(
                        log_line=idx,
                        log_time=stamp,
                        raw_line=rendered_lines[idx],
                        body=body,
                        level=detect_level(body),
                        path="-",
                        log_idle_msecs=0,
                    )
                )
            return Source(display_path="-", kind="stdin", log_entries=entries, plain_lines=[])

        plain_lines = [PlainLine(raw_line=line, path="-", line_no=i) for i, line in enumerate(rendered_lines)]
        return Source(display_path="-", kind="stdin", log_entries=[], plain_lines=plain_lines)

    def apply_time_cutoffs(self, source: Source) -> list[Entry] | None:
        if not source.log_entries or (self.since_dt is None and self.until_dt is None):
            return list(source.log_entries)

        filtered = [
            entry
            for entry in source.log_entries
            if (self.since_dt is None or entry.log_time >= self.since_dt)
            and (self.until_dt is None or entry.log_time <= self.until_dt)
        ]
        if filtered:
            return filtered
        if source.kind != "file":
            return []
        return None

    def build_out_of_range_error(self, source: Source) -> list[str]:
        assert source.file_mtime is not None
        lines = [
            f"  error: unable to open file: {Path(source.display_path).resolve()}",
            f" reason: file contents are out-of-range of time cutoffs “{Path(source.display_path).resolve()}”",
        ]
        file_time = format_sql_time(source.file_mtime)
        lines.append(f" |        = note: File time range is “{file_time}” to “{file_time}”")
        if self.since_dt is not None:
            lines.append(f" |        = note: Minimum time cutoff is “{format_sql_time(self.since_dt)}”")
        if self.until_dt is not None:
            lines.append(f" |        = note: Maximum time cutoff is “{format_sql_time(self.until_dt)}”")
        return lines


def parse_args(argv: Sequence[str]) -> Options:
    opts = Options()
    args = list(argv[1:])
    idx = 0
    while idx < len(args):
        arg = args[idx]

        if arg == "--help":
            opts.help = True
        elif arg == "-h":
            opts.help = True
        elif arg == "-H":
            opts.internal_help = True
        elif arg == "-V":
            opts.version = True
        elif arg == "-u":
            opts.update_formats = True
        elif arg == "-r":
            opts.recursive = True
        elif arg == "-R":
            opts.load_rotated = True
        elif arg == "-n":
            opts.headless = True
        elif arg == "-N":
            opts.no_default = True
        elif arg == "-q":
            opts.quiet = True
        elif arg == "-t":
            opts.prepend_stdin_timestamps = True
        elif arg == "-C":
            opts.check_config = True
        elif arg == "-W":
            pass
        elif arg == "-m":
            opts.management_mode = True
        elif arg in ("-S", "--since"):
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "--since: 1 required TEXT missing")
            opts.since_text = args[idx]
        elif arg in ("-U", "--until"):
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "--until: 1 required TEXT missing")
            opts.until_text = args[idx]
        elif arg == "-d":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-d: 1 required FILE missing")
            opts.debug_file = args[idx]
        elif arg == "-I":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-I: 1 required TEXT:DIR missing")
            opts.extra_config_dirs.append(args[idx])
        elif arg == "-c":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-c: 1 required  missing")
            opts.command_options.append(args[idx])
        elif arg == "-f":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-f: 1 required  missing")
            opts.command_files.append(args[idx])
        elif arg == "-e":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-e: 1 required  missing")
            opts.shell_commands.append(args[idx])
        elif arg == "-i":
            idx += 1
            if idx >= len(args):
                raise ParseError(107, "invalid command-line arguments", "-i requires file")
            opts.install_arg = args[idx]
        elif arg.startswith("-"):
            remainder = " ".join(args[idx:])
            if " " in remainder:
                reason = f"The following arguments were not expected: {remainder}"
            else:
                reason = f"The following argument was not expected: {arg}"
            raise ParseError(109, "invalid command-line arguments", reason)
        else:
            opts.paths.append(arg)
        idx += 1

    if opts.management_mode and (opts.headless or opts.no_default):
        unexpected = []
        if opts.no_default:
            unexpected.append("-N")
        if opts.headless:
            unexpected.append("-n")
        raise ParseError(109, "invalid command-line arguments", f"The following arguments were not expected: {' '.join(unexpected)}")

    return opts


def parse_cutoff(value: str, name: str) -> datetime:
    parsed = parse_timestamp(value)
    if parsed is None:
        raise RuntimeCliError(1, [f"  error: invalid '{name}' time “{value}”", " reason: Unrecognized input"])
    return parsed


def execute_commands(runtime: RuntimeContext, state: State) -> None:
    commands: list[tuple[str, str, int]] = []

    for index, command in enumerate(runtime.opts.command_options, start=1):
        commands.append(("option", command, index))

    option_count = len(commands)
    for offset, command_file in enumerate(runtime.opts.command_files, start=1):
        commands.extend(read_script_command_file(command_file, option_count + offset))

    for source_kind, command, index in commands:
        if not command:
            continue
        prefix = command[0]
        if prefix not in ":;|":
            sys.stderr.write(INVALID_C_HELP.format(cmd=command))
            raise RuntimeCliError(105, [])

        if prefix == ":":
            run_builtin_command(state, command[1:].strip(), index)
        elif prefix == ";":
            execute_sql_command(state, command[1:], index)
        elif prefix == "|":
            execute_script(state, command[1:], index)


def read_script_command_file(path: str, index: int) -> list[tuple[str, str, int]]:
    if path == "-":
        text = sys.stdin.read()
    else:
        target = Path(path)
        if not target.exists():
            sys.stderr.write(
                f"  error: unknown script -- {path} -- file not found\n"
                f" --> command-option:{index}\n"
                f" | |{path:<35}\n"
            )
            return []
        text = target.read_text(encoding="utf-8")

    commands = []
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        commands.append(("script", stripped, index))
    return commands


def execute_script(state: State, script_ref: str, index: int) -> None:
    commands = read_script_command_file(script_ref, index)
    for _, command, inner_index in commands:
        prefix = command[0]
        if prefix == ":":
            run_builtin_command(state, command[1:].strip(), inner_index)
