def format_table(result: QueryResult) -> str:
    if not result.columns:
        return ""

    formatted_rows = [tuple(format_value(value) for value in row) for row in result.rows]
    widths = [len(column) for column in result.columns]
    numeric = [all(isinstance(row[idx], (int, float)) and not isinstance(row[idx], bool) for row in result.rows) for idx in range(len(result.columns))]

    for row in formatted_rows:
        for idx, value in enumerate(row):
            widths[idx] = max(widths[idx], len(value))

    def format_cell(value: str, idx: int, *, header: bool = False) -> str:
        width = widths[idx]
        if header:
            return f" {value:<{width}} "
        if numeric[idx]:
            return f" {value:>{width}} "
        return f" {value:<{width}} "

    lines = []
    lines.append("".join(format_cell(column, idx, header=True) for idx, column in enumerate(result.columns)).rstrip() + " \n")
    for row in formatted_rows:
        lines.append("".join(format_cell(value, idx) for idx, value in enumerate(row)).rstrip() + " \n")
    return "".join(lines)


