def record_is_log_like(record: LogRecord) -> bool:
    return record.time is not None or "-[-]" in record.rendered


def load_path_records(options: Options, path_text: str, direct: bool = True) -> list[LogRecord]:
    if path_text == "-":
        return load_stdin_records(options, explicit_dash=True)
    expanded = expand_path(path_text)
    records: list[LogRecord] = []
    for path in expanded:
        if path.is_dir():
            records.extend(load_directory_records(path, options))
            continue
        if not path.exists():
            raise FileNotFoundError(path)
        records.extend(load_file_records(path, include_plain=direct))
        if options.include_rotated:
            for rotated in rotated_paths(path):
                if rotated.exists() and rotated != path:
                    records.extend(load_file_records(rotated, include_plain=False))
    return records


def expand_path(path_text: str) -> list[Path]:
    if any(char in path_text for char in "*?[]"):
        matches = [Path(match) for match in sorted(Path().glob(path_text))]
        return matches if matches else [Path(path_text)]
    return [Path(path_text)]


def rotated_paths(path: Path) -> list[Path]:
    parent = path.parent
    prefix = path.name + "."
    rotated = [child for child in parent.iterdir() if child.name.startswith(prefix) and child.is_file()]
    return sorted(rotated)


def load_directory_records(path: Path, options: Options) -> list[LogRecord]:
    records: list[LogRecord] = []
    iterator: Iterable[Path]
    if options.recursive:
        iterator = (child for child in path.rglob("*") if child.is_file())
    else:
        iterator = (child for child in path.iterdir() if child.is_file())
    for child in sorted(iterator):
        child_records = load_file_records(child, include_plain=False)
        records.extend(child_records)
    return records


def load_file_records(path: Path, include_plain: bool) -> list[LogRecord]:
    text = read_source_text(path)
    records: list[LogRecord] = []
    for line_no, raw in enumerate(text.splitlines(True), start=1):
        json_record = parse_json_line(raw, str(path), line_no)
        if json_record is not None:
            records.append(json_record)
            continue
        line_record = parse_log_line(raw, str(path), line_no)
        if not include_plain and not record_is_log_like(line_record):
            continue
        records.append(line_record)
    return records


def load_stdin_records(options: Options, explicit_dash: bool) -> list[LogRecord]:
