def load_exec_records(command: str) -> list[LogRecord]:
    completed = subprocess.run(
        command,
        shell=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    records: list[LogRecord] = []
    for line_no, raw in enumerate(completed.stdout.splitlines(True), start=1):
        json_record = parse_json_line(raw, command, line_no)
        if json_record is not None:
            records.append(json_record)
            continue
        records.append(parse_log_line(raw, command, line_no))
    return records


def dedupe_and_sort(records: list[LogRecord]) -> list[LogRecord]:
    seen: set[str] = set()
    deduped: list[LogRecord] = []
    for record in records:
        key = record.rendered
        if key in seen:
            continue
        seen.add(key)
        deduped.append(record)
    if all(record.time is not None for record in deduped):
        deduped.sort(
            key=lambda record: (
                record.time,
                record.rendered,
                record.path,
                record.line_no,
            )
        )
    return deduped


def filter_by_time(records: list[LogRecord], since: datetime | None, until: datetime | None) -> list[LogRecord]:
    filtered: list[LogRecord] = []
    for record in records:
        if record.time is None:
            if since is None and until is None:
                filtered.append(record)
            continue
